// Hand-written `@koa/router` stub for the flowatlas fixture suite.
//
// The verbs live here rather than on the application, and so does the prefix:
// a Koa router usually carries it as a constructor option, which is why a
// prefix can be an option on this framework's row and is an argument on every
// other one. `del` is the alias for `delete`, which is a reserved word.

import type { Context, Middleware, Next } from 'koa';

export interface RouterOptions {
  prefix?: string;
}

export declare class Router {
  constructor(options?: RouterOptions);
  get(path: string, ...handlers: Middleware[]): Router;
  post(path: string, ...handlers: Middleware[]): Router;
  put(path: string, ...handlers: Middleware[]): Router;
  patch(path: string, ...handlers: Middleware[]): Router;
  delete(path: string, ...handlers: Middleware[]): Router;
  del(path: string, ...handlers: Middleware[]): Router;
  all(path: string, ...handlers: Middleware[]): Router;
  use(...handlers: Middleware[]): Router;
  use(path: string, ...handlers: Middleware[]): Router;
  prefix(path: string): Router;
  routes(): Middleware;
  allowedMethods(): Middleware;
}

export default Router;
export type { Context, Next };
